<?php
declare(strict_types=1);
$statusLabels=['draft'=>'Taslak','confirmed'=>'Onaylandı','processing'=>'Hazırlanıyor','shipped'=>'Kargolandı','completed'=>'Tamamlandı','cancelled'=>'İptal'];
?>
<section class="module-toolbar"><div><p class="module-intro">Satış siparişlerinizi ve süreçlerini takip edin.</p><span class="result-count"><?= number_format($total,0,',','.') ?> sipariş</span></div><?php if(kd_can('orders.manage')): ?><a class="btn primary action-link" href="index.php?page=orders&action=create">＋ Yeni sipariş</a><?php endif; ?></section>
<section class="panel customer-list-panel"><form class="filter-bar" method="get"><input type="hidden" name="page" value="orders"><label class="filter-search"><span>⌕</span><input type="search" name="q" value="<?= kd_e($q) ?>" placeholder="Sipariş no veya müşteri ara"></label><select name="status"><option value="">Tüm durumlar</option><?php foreach($statusLabels as $key=>$label): ?><option value="<?= kd_e($key) ?>" <?= $status===$key?'selected':'' ?>><?= kd_e($label) ?></option><?php endforeach; ?></select><button class="btn secondary">Filtrele</button><?php if($q!==''||$status!==''): ?><a class="clear-filter" href="index.php?page=orders">Temizle</a><?php endif; ?></form>
<div class="table-wrap"><table class="data-table"><thead><tr><th>Sipariş</th><th>Müşteri</th><th>Depo</th><th>Tarih</th><th>Tutar</th><th>Durum</th><th></th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td><a class="customer-name" href="index.php?page=orders&action=view&id=<?= (int)$order['id'] ?>"><?= kd_e($order['order_number']) ?></a><small class="table-sub"><?= (int)$order['id'] ?></small></td><td><?= kd_e($order['customer_name']?:'Misafir müşteri') ?></td><td><?= kd_e($order['warehouse_name']?:'—') ?></td><td><?= kd_e(date('d.m.Y',strtotime((string)$order['created_at']))) ?></td><td><strong><?= number_format((float)$order['grand_total'],2,',','.') ?> ₺</strong></td><td><span class="order-status status-<?= kd_e($order['status']) ?>"><?= kd_e($statusLabels[$order['status']]??$order['status']) ?></span></td><td class="table-actions"><a href="index.php?page=orders&action=view&id=<?= (int)$order['id'] ?>">↗</a></td></tr><?php endforeach; ?><?php if(!$orders): ?><tr><td colspan="7"><div class="empty-state"><strong>Henüz sipariş bulunmuyor</strong><p>İlk satış siparişinizi oluşturarak başlayın.</p></div></td></tr><?php endif; ?></tbody></table></div>
<?php if($pages>1): ?><div class="pagination"><span><?= $page ?> / <?= $pages ?> sayfa</span><div><?php if($page>1): ?><a href="<?= kd_e('index.php?page=orders&q='.rawurlencode($q).'&status='.rawurlencode($status).'&p='.($page-1)) ?>">← Önceki</a><?php endif; ?><?php if($page<$pages): ?><a href="<?= kd_e('index.php?page=orders&q='.rawurlencode($q).'&status='.rawurlencode($status).'&p='.($page+1)) ?>">Sonraki →</a><?php endif; ?></div></div><?php endif; ?></section>
